<script setup>
import ReasonDisclosure from '@/shared/ReasonDisclosure.vue'



import {computed, inject, ref, watch} from 'vue'


const props=defineProps({model:Object,disabled:Boolean,forceOpen:Boolean})
const api=inject('api'),environments=ref([]),busy=ref(false),error=ref(''),loaded=ref(false),scripts=new WeakMap()
const overrides=computed(()=>props.model.environment_overrides||[])
async function load(){if(loaded.value||busy.value)return;busy.value=true;error.value='';try{const data=await api('api/environments');if(!Array.isArray(data))throw Error('环境列表响应无效');environments.value=data;loaded.value=true}catch(e){error.value=e.message}finally{busy.value=false}}
function add(){props.model.environment_overrides=[...overrides.value,{environment:'',content:props.model.content||'',reason:''}]}
function remove(index){const entries=overrides.value.filter((_,i)=>i!==index);if(entries.length)props.model.environment_overrides=entries;else delete props.model.environment_overrides}
function mode(entry,value){if(value==='skip'){scripts.set(entry,entry.content||'');entry.skip=true;delete entry.content}else{entry.skip=false;entry.content=scripts.get(entry)??props.model.content??''}}
function options(entry){const values=environments.value.filter(e=>e.name===entry.environment||!overrides.value.some(x=>x.environment===e.name)).map(e=>({value:e.name,label:e.display_name||e.name}));if(entry.environment&&!values.some(e=>e.value===entry.environment))values.push({value:entry.environment,label:entry.environment+'（请确认环境仍有效）'});return values}
const expanded=ref([])
watch(()=>props.forceOpen,v=>{if(v){expanded.value=['panel'];load()}},{immediate:true})

import OptionPicker from '../../shared/components/OptionPicker.vue'



import {Accordion,AccordionContent,AccordionItem,AccordionTrigger,Button,Field,FieldLabel,Input,Textarea} from '../../shared/shadcn-ui.js'
</script>
<template><Field data-field="max_affected_rows"><FieldLabel as="div">允许影响行数</FieldLabel><Input v-model.number="model.max_affected_rows" type="number" :disabled="disabled"/></Field><Field data-field="sql" class="sql-span"><FieldLabel as="div">SQL 脚本</FieldLabel><Textarea v-model="model.content" :disabled="disabled" placeholder="默认用于所有环境；保存原文草稿，就绪和执行前分别校验。" :rows="({minRows:(7),maxRows:Math.max((7),16)}).minRows||4"/></Field><Accordion v-if="!model.data_sync" data-field="sql_environment_overrides" class="sql-environment-settings sql-span platform-collapse" type="multiple" :model-value="(expanded||[]).map(String)" @update:model-value="expanded=$event;(keys=>{if(keys.length)load()})($event)"><AccordionItem :value="String(&quot;panel&quot;)"><AccordionTrigger>高级设置<span v-if="overrides.length"> · {{overrides.length}} 个环境例外</span><span v-else> · 特定环境使用不同 SQL 或无需执行</span></AccordionTrigger><AccordionContent force-mount v-show="!(!(expanded||[]).map(String).includes(String(&quot;panel&quot;)))"><p>未设置例外的环境使用上方 SQL。环境专用脚本会单独预检、审批，其他环境执行成功不代表此脚本已验证。</p><p v-if="error" role="alert">环境读取失败：{{error}} <Button @click="load" variant="ghost" size="default" type="button">重试读取环境</Button></p><p v-if="busy" role="status">正在读取环境…</p><article v-for="(entry,index) in overrides" :key="index" class="sql-environment-entry"><div class="sql-environment-heading"><b>环境例外 {{index+1}}</b><Button v-if="!disabled" @click="remove(index)" variant="ghost" size="default" type="button">移除环境例外</Button></div><div class="sql-environment-grid"><Field ><FieldLabel as="div">目标环境</FieldLabel><OptionPicker v-model="entry.environment" :options="options(entry)" :disabled="disabled||busy" placeholder="请选择环境" :style="{width:'100%',maxWidth:'100%'}"/></Field><Field ><FieldLabel as="div">执行方式</FieldLabel><OptionPicker :model-value="entry.skip?'skip':'script'" :options="[{value:'script',label:'使用专用 SQL'},{value:'skip',label:'该环境无需执行'}]" :disabled="disabled" :style="{width:'100%',maxWidth:'100%'}" @update:model-value="value=>mode(entry,value)"/></Field></div><Field v-if="!entry.skip"><FieldLabel as="div">环境专用 SQL</FieldLabel><Textarea v-model="entry.content" :disabled="disabled" placeholder="填写此环境实际执行的完整脚本" :rows="({minRows:(5),maxRows:Math.max((5),16)}).minRows||4"/></Field><ReasonDisclosure :key="entry.environment" :required="environments.find(e=>e.name===entry.environment)?.protected !== false" :filled="!!entry.reason"><Field ><FieldLabel as="div">{{entry.skip?'无需执行的原因':'使用不同 SQL 的原因'}}</FieldLabel><Input v-model="entry.reason" :disabled="disabled" placeholder="请说明原因，随本次交付一同审核和留档"/></Field></ReasonDisclosure></article><Button v-if="!disabled" @click="add" variant="outline" size="default" type="button" :disabled="(busy||!loaded||overrides.length>=20)">＋ 添加环境例外</Button></AccordionContent></AccordionItem></Accordion></template>
<style scoped>.sql-span{grid-column:1/-1}.sql-environment-settings{font-size:.75rem;min-width:0}.sql-environment-settings p{color:var(--muted-foreground)}.sql-environment-settings p{line-height:1.7;margin:10px 0;overflow-wrap:anywhere}.sql-environment-entry{display:grid;gap:12px;padding:12px;margin:12px 0;background:var(--panel2);border:1px solid var(--border);border-radius:var(--radius);min-width:0}.sql-environment-heading{display:flex;align-items:center;justify-content:space-between;gap:8px}.sql-environment-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}label{display:grid;gap:7px;min-width:0}@media(max-width:700px){.sql-environment-grid{grid-template-columns:1fr}}</style>
